#!/bin/sh
# Wraps src.html (the page, also published as the PlainStats artifact) into index.html, which Vercel serves.
cd "$(dirname "$0")"
{
  printf '%s\n' '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>PlainStats: NFL contracts, salary cap and player stats</title><meta name="description" content="NFL contracts, stats and team analytics, explained in plain English."><link rel="canonical" href="https://www.plainstatsnfl.com/"><meta property="og:type" content="website"><meta property="og:site_name" content="PlainStats"><meta property="og:title" content="PlainStats: NFL contracts, salary cap and player stats"><meta property="og:description" content="NFL contracts, stats and team analytics, explained in plain English."><meta property="og:url" content="https://www.plainstatsnfl.com/"><meta property="og:image" content="https://www.plainstatsnfl.com/og-image.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="PlainStats: every NFL contract and stat, explained in plain English"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="PlainStats: NFL contracts, salary cap and player stats"><meta name="twitter:description" content="NFL contracts, stats and team analytics, explained in plain English."><meta name="twitter:image" content="https://www.plainstatsnfl.com/og-image.png"><meta name="theme-color" content="#f5f5f7" media="(prefers-color-scheme: light)"><meta name="theme-color" content="#000000" media="(prefers-color-scheme: dark)"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-title" content="PlainStats"><link rel="manifest" href="manifest.json"><link rel="icon" href="icon.svg" type="image/svg+xml"><link rel="icon" href="favicon.ico" sizes="48x48"><link rel="preconnect" href="https://a.espncdn.com"><script type="application/ld+json">{"@context":"https://schema.org","@type":"WebSite","name":"PlainStats","url":"https://www.plainstatsnfl.com/","description":"NFL contracts, stats and team analytics, explained in plain English."}</script><link rel="apple-touch-icon" href="icon-180.png"><style>:root{color-scheme:light;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}body{margin:0}img{max-width:100%}</style></head><body>'
  cat src.html
  printf '\n%s\n' '</body></html>'
} > index.html
